import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        System.out.println(a + b);
    }
}

public class Main {
    public static void main(String[] args) {
        int sum = 10;
        String label = "Answer";
        System.out.println(sum);
        System.out.println(label);
    }
}

